import{_ as e,o as d,c as o,a4 as a}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"HomeSense L2 中文嵌入模型 — 完整复盘（试错 / 换思路 / 正确路径）","description":"","frontmatter":{"title":"HomeSense L2 中文嵌入模型 — 完整复盘（试错 / 换思路 / 正确路径）","date":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense-L2-嵌入模型复盘.md","filePath":"posts/HomeSense-L2-嵌入模型复盘.md"}'),n={name:"posts/HomeSense-L2-嵌入模型复盘.md"};function r(i,t,l,s,g,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="homesense-l2-中文嵌入模型-—-完整复盘-试错-换思路-正确路径" tabindex="-1">HomeSense L2 中文嵌入模型 — 完整复盘（试错 / 换思路 / 正确路径） <a class="header-anchor" href="#homesense-l2-中文嵌入模型-—-完整复盘-试错-换思路-正确路径" aria-label="Permalink to &quot;HomeSense L2 中文嵌入模型 — 完整复盘（试错 / 换思路 / 正确路径）&quot;">​</a></h1><blockquote><p>日期：2026-09-02 项目：HomeSense v5 执行端意图匹配（手机/盒子本地，零云端） 结论先行：最终锁定 <strong>bge-small-zh-v1.5 INT8 ONNX + onnxruntime-purego（纯 Go，无 cgo）</strong>，maxLen=128 本地推理，并把下一个版本升级为「BM25 + embedding + fingerprint」混合检索。</p></blockquote><hr><h2 id="一、整个决策过程-换思路-5-次" tabindex="-1">一、整个决策过程（换思路 5 次） <a class="header-anchor" href="#一、整个决策过程-换思路-5-次" aria-label="Permalink to &quot;一、整个决策过程（换思路 5 次）&quot;">​</a></h2><h3 id="_1-起点-中转站-api-出问题" tabindex="-1">1. 起点：中转站 API 出问题 <a class="header-anchor" href="#_1-起点-中转站-api-出问题" aria-label="Permalink to &quot;1. 起点：中转站 API 出问题&quot;">​</a></h3><ul><li>项目里有 pie-xian 中转站的 key，一开始想用它的 <code>/v1/embeddings</code> 当云端 embedding。</li><li><strong>教训 1</strong>：用 curl 反复探测中转站模型列表，触发了中转站的限流/风控，key 一度被临时封（返回「无效令牌」）。之后 key 恢复，但确认了「别人的中转站别乱测、别依赖」。</li><li>中转站 <code>all-mpnet-base-v2</code>（768 维，110M 参数，7 个 embedding 模型里最小）。</li><li><strong>决策 1</strong>：不依赖中转站，转本地。</li></ul><h3 id="_2-云端免费资源排查-绕了一大圈" tabindex="-1">2. 云端免费资源排查（绕了一大圈） <a class="header-anchor" href="#_2-云端免费资源排查-绕了一大圈" aria-label="Permalink to &quot;2. 云端免费资源排查（绕了一大圈）&quot;">​</a></h3><ul><li>查了 HuggingFace Serverless API（免费，~$0.10/月额度、限速）、Cloudflare Workers AI（只有 bge-English，无中文可用）、模力方舟 ai.gitee.com（每天 100 次免费，但不含目标任务）。</li><li><strong>结论 2</strong>：没有「永久免费 + 中文好 + all-mpnet-base-v2」的云端方案；要中文好必须本地。</li></ul><h3 id="_3-目标模型选择-中文本地小模型对比" tabindex="-1">3. 目标模型选择：中文本地小模型对比 <a class="header-anchor" href="#_3-目标模型选择-中文本地小模型对比" aria-label="Permalink to &quot;3. 目标模型选择：中文本地小模型对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>参数</th><th>INT8 体积</th><th>维度</th><th>中文</th></tr></thead><tbody><tr><td>all-mpnet-base-v2</td><td>110M</td><td>~23MB(模型)</td><td>768</td><td>英文向</td></tr><tr><td>bge-base-zh-v1.5</td><td>102M</td><td>~100MB</td><td>768</td><td>✓</td></tr><tr><td><strong>bge-small-zh-v1.5</strong></td><td><strong>24M</strong></td><td><strong>~23MB</strong></td><td><strong>512</strong></td><td>✓ C-MTEB 57.8</td></tr><tr><td>Qwen3-Embedding-0.6B</td><td>633M</td><td>~600MB</td><td>1024</td><td>✓ 但太大</td></tr></tbody></table><p><strong>决策 3</strong>：bge-small-zh-v1.5。体积最小、中文优化、手机可跑。（曾纠结 512 维不能和 768 维互查，后来放弃云端混查，全走本地。）单文件核对了 ONNX 各变体体积：INT8 23MB 反而是最小的（q4 50MB、q4f16 28MB、fp16 45MB），<strong>用 INT8 版</strong>。</p><h3 id="_4-运行方案大弯路-从「go-直接绑-ort」到「purego」" tabindex="-1">4. 运行方案大弯路：从「Go 直接绑 ORT」到「purego」 <a class="header-anchor" href="#_4-运行方案大弯路-从「go-直接绑-ort」到「purego」" aria-label="Permalink to &quot;4. 运行方案大弯路：从「Go 直接绑 ORT」到「purego」&quot;">​</a></h3><ul><li>用户明确 <strong>不要 Python、不要打包 Python、手机 Termux 上也不装</strong> → 排除 Python 子进程。</li><li>试 <code>yalue/onnxruntime_go</code>（cgo 绑定）： <ul><li><strong>教训 4</strong>：该库 <code>ORT_API_VERSION</code> 和官方预编译 <code>libonnxruntime.so</code> 版本对不上（要 29，释出只有 1~20/1~23），折腾各种版本组合全部失败。</li><li><strong>换思路</strong>：用 <code>github.com/shota3506/onnxruntime-purego</code> —— <strong>purego 动态加载 .so，零 cgo</strong>，跨平台无编译地狱。只支持 ORT 1.23.x（API v23），下载 aarch64 版 <code>onnxruntime-linux-aarch64-1.23.1.tgz</code>（注意：curl 不带 -L 会 404，用 wget 成功）。</li></ul></li></ul><h3 id="_5-效果翻车与关键修复-cls-sep" tabindex="-1">5. 效果翻车与关键修复（CLS/SEP） <a class="header-anchor" href="#_5-效果翻车与关键修复-cls-sep" aria-label="Permalink to &quot;5. 效果翻车与关键修复（CLS/SEP）&quot;">​</a></h3><ul><li>模型加载成功后，相似度偏低：「我要回家了」vs「回家模式」只有 0.53。</li><li><strong>以为模型烂</strong>，排查方向：指令前缀（BGE 检索式指令反而更差）、中文分词（其实正常）、Go 端 vs Python 官方输出对照。</li><li><strong>真正根因</strong>：<code>sugarme/tokenizer</code> 的 <code>EncodeSingle(text)</code> 默认<strong>不加 <code>[CLS]</code>/<code>[SEP]</code></strong>。训练时输入 <code>[CLS] 句子 [SEP]</code>，缺了就向量错位。改成 <code>EncodeSingle(text, true)</code> 后： <ul><li>&quot;我要回家了&quot;vs&quot;回家模式&quot; 0.53 → <strong>0.65</strong></li><li>&quot;把声音调小一点&quot;vs&quot;调低音量&quot; 0.54 → <strong>0.72</strong></li></ul></li><li>另一个 panic 坑：<code>tokenizer.NewTokenizerFromFile</code> 是<strong>空 TODO</strong>返回 nil，必须用 <code>pretrained.FromFile</code>。</li></ul><h3 id="_6-本地速度优化" tabindex="-1">6. 本地速度优化 <a class="header-anchor" href="#_6-本地速度优化" aria-label="Permalink to &quot;6. 本地速度优化&quot;">​</a></h3><ul><li>默认 <code>maxLen=512</code>：x86_64 ~164ms/次；意图文本都 ≤10 字，降到 <strong>128</strong> → <strong>~33ms/次</strong>（约 5 倍），手机 ARM64 预估 150-300ms。</li><li>部署体积：模型 24MB + libonnxruntime 18MB + binary ≈ 42MB。</li></ul><hr><h2 id="二、效果实测-9-意图-×-55-说法" tabindex="-1">二、效果实测（9 意图 × 55 说法） <a class="header-anchor" href="#二、效果实测-9-意图-×-55-说法" aria-label="Permalink to &quot;二、效果实测（9 意图 × 55 说法）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阈值</th><th>召回率</th><th>误报</th></tr></thead><tbody><tr><td>0.60</td><td>88%</td><td>4/14</td></tr><tr><td>0.65</td><td>84%</td><td>6/14</td></tr><tr><td>0.70</td><td>84%</td><td>8/14</td></tr></tbody></table><p>强同义（放→播放新闻联播 0.96、投屏 0.93）很好；嵌入可正确拒绝无关输入（天气/外卖）。</p><h3 id="暴露的两个硬伤-纯-embedding-单通道通病" tabindex="-1">暴露的两个硬伤（纯 embedding 单通道通病） <a class="header-anchor" href="#暴露的两个硬伤-纯-embedding-单通道通病" aria-label="Permalink to &quot;暴露的两个硬伤（纯 embedding 单通道通病）&quot;">​</a></h3><ol><li><strong>反义误报</strong>：「打开灯」→「关灯」0.68、「离家模式」→「回家模式」0.80。embedding 认语义近不认方向。</li><li><strong>口语简写漏报</strong>：「小声点」「开冷气」「我到家了」单锚点相似度不足(0.55)。</li></ol><hr><h2 id="三、业界调研结论-怎么继续" tabindex="-1">三、业界调研结论（怎么继续） <a class="header-anchor" href="#三、业界调研结论-怎么继续" aria-label="Permalink to &quot;三、业界调研结论（怎么继续）&quot;">​</a></h2><p>看了 Google(EMNLP 2025)、ACL 2023 zero/few-shot、Nature 端侧意图、Qdrant Edge、HuggingFace 讨论、中文生产案例(86%→97%)：</p><ol><li><strong>纯 embedding 不是主流</strong>，生产用 <strong>混合检索</strong>：BM25 词面 + embedding 语义 + RRF 融合。</li><li><strong>意图卡片</strong>（Intent Card）替代单文本锚点：每个 intent 给多个 positive 说法 + negative 反例 + 混淆意图。</li><li><strong>规则优先分流</strong>：先判断「是不是意图问题/方向对不对」，再给模型。L1 规则引擎先拦开关类。</li><li>模型上：RoBERTa/XLNet-Base 或 bge-small 足够，<strong>换策略收益 &gt;&gt; 换模型</strong>。</li></ol><hr><h2 id="四、下一步-已确认要做的" tabindex="-1">四、下一步（已确认要做的） <a class="header-anchor" href="#四、下一步-已确认要做的" aria-label="Permalink to &quot;四、下一步（已确认要做的）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>workflow_match 升级为 3 通道：</span></span>
<span class="line"><span>① fingerprint 精确   (0.1ms, 已有)</span></span>
<span class="line"><span>② BM25 词面         (0.1ms, 手写~50行)</span></span>
<span class="line"><span>③ embedding 语义    (33ms, 已有)</span></span>
<span class="line"><span>      ↓ RRF 融合 + 意图卡片(positive/negative) 校准</span></span></code></pre></div><p>配套改动：</p><ul><li>workflow JSON 加 <code>intents</code>（positive 说法）+ <code>negative_examples</code>（反例）</li><li><code>LoadWorkflows</code> 把每个 intent 生成 fingerprint+embedding 入库</li><li>默认阈值 0.65（原 0.75）</li><li>预期：召回 88% → ~97%，误报 4/14 → ~1/14</li></ul><hr><h2 id="五、踩坑清单-速查" tabindex="-1">五、踩坑清单（速查） <a class="header-anchor" href="#五、踩坑清单-速查" aria-label="Permalink to &quot;五、踩坑清单（速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>坑</th><th>修法</th></tr></thead><tbody><tr><td>1</td><td>别乱测别人中转站 API / 别依赖</td><td>key 可能被封，转本地</td></tr><tr><td>2</td><td>AND 中转站只有 all-mpnet-base-v2 等英文向</td><td>中文要本地 bge-*</td></tr><tr><td>3</td><td>yalue/onnxruntime_go 版本对不上</td><td>换 onnxruntime-purego（零 cgo）</td></tr><tr><td>4</td><td>ORT 下载 curl 无 -L 会 404</td><td>用 wget 或 curl -L</td></tr><tr><td>5</td><td>EncodeSingle 默认不加 CLS/SEP</td><td><code>EncodeSingle(text, true)</code></td></tr><tr><td>6</td><td>NewTokenizerFromFile 是空 TODO</td><td>用 <code>pretrained.FromFile</code></td></tr><tr><td>7</td><td>ONNX external data 名不能改</td><td>model_quantized.onnx + .onnx_data 成对</td></tr><tr><td>8</td><td>512 太长慢(~164ms)</td><td>maxLen=128 → ~33ms</td></tr><tr><td>9</td><td>purego 只支持 ORT 1.23.x</td><td>锁 libonnxruntime v1.23.1</td></tr><tr><td>10</td><td>ARM64 vs x86_64 .so 别混</td><td>部署 ARM64，本地测试换 x64 测完换回</td></tr><tr><td>11</td><td>别当模型「烂」就换</td><td>先查 CLS/SEP、分词、阈值，再谈换模型</td></tr></tbody></table>`,35)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
